def esc(value: object) -> str:
    return html.escape(str(value), quote=True)

def parse_prompts():
    blocks = re.split(r"(?=^## Bài \d+ [–-])", PROMPTS, flags=re.M)
    out = []
    for block in blocks:
        m = re.match(r"## Bài (\d+) [–-] (.+)", block)
        if not m:
            continue
        number = int(m.group(1))
        text = block.split("````", 2)[1] if "````" in block else block
        def line(prefix):
            found = re.search(r"^" + re.escape(prefix) + r"\s*(.+)$", text, re.M)
            return found.group(1).strip() if found else ""
        bullets = re.findall(r"^- (.+)$", text, re.M)
        out.append(dict(number=number, title=m.group(2).strip(), goal=line("Mục tiêu:"), pre=line("Kiến thức cần có:"), bullets=bullets, practice=line("Thực hành:"), errors=line("Lỗi thường gặp:")))
    return out

PROMPT_DATA = parse_prompts()
