JS = r"""
(() => {
const cfg = JSON.parse(document.getElementById('lesson-config').textContent);
const range=document.getElementById('param'), val=document.getElementById('param-value'), out=document.getElementById('readout');
const canvas=document.getElementById('lab-canvas'), ctx=canvas.getContext('2d');
let running=true,t=0,last=0;
function compute(x){let y=0,s='';switch(cfg.mode){
case 'motor':y=(x-60)/40;s=`Rotor 1 ${x.toFixed(0)}%: lực nâng thay đổi; roll/pitch/yaw phụ thuộc vị trí và chiều quay rotor.`;break;
case 'hover':y=x*9.81/4;s=`Hover: T = ${(x*9.81).toFixed(2)} N; mỗi rotor ${(x*9.81/4).toFixed(2)} N.`;break;
case 'pitch':y=Math.sin(x*Math.PI/180);s=`Pitch ${x.toFixed(0)}°; cos(pitch) = ${Math.cos(x*Math.PI/180).toFixed(3)}${Math.abs(x)>85?' — gần kỳ dị Euler ZYX.':''}`;break;
case 'accel':y=(x-1.2*9.81)/1.2;s=`Với m=1,2 kg, gia tốc z = ${y.toFixed(2)} m/s² (ENU, bỏ qua cản).`;break;
case 'drift':y=x*60;s=`Không bù bias: sau 60 s góc trôi khoảng ${y.toFixed(1)}°.`;break;
case 'pid':y=x/3;s=`Kp = ${x.toFixed(2)}. Tăng Kp giúp phản ứng nhanh hơn nhưng dễ vọt lố; đồ thị là minh họa plant chuẩn hóa.`;break;
case 'filter':y=x;s=`α = ${x.toFixed(3)}; trọng số accel = ${(1-x).toFixed(3)}.`;break;
case 'step':y=50/x;s=`dt=${x.toFixed(0)} ms → ${Math.round(10000/x)} bước cho 10 s; dt lớn làm sai số tăng.`;break;
case 'delay':y=x/40;s=`Trễ ${x.toFixed(0)} ms; pha trễ tại 5 Hz xấp xỉ ${(x*360*5/1000).toFixed(0)}°.`;break;
case 'track':y=x*x/4;s=`Vận tốc ${x.toFixed(1)} m/s; với bán kính 2 m, gia tốc hướng tâm ${(x*x/2).toFixed(2)} m/s².`;break;
case 'ratio':y=x/(1.2*9.81);s=`Drone 1,2 kg: tỷ số thrust/weight = ${y.toFixed(2)}.`;break;
case 'thrust':y=1.2e-5*x*x;s=`Giả định kT=1,2×10⁻⁵: T≈${y.toFixed(2)} N tại ω=${x.toFixed(0)} rad/s.`;break;
case 'battery':y=x;s=`${x.toFixed(2)} V/cell: ${x<3.4?'mức thấp, kích hoạt logic failsafe giả lập':x<3.6?'cảnh báo pin thấp':'mức theo dõi bình thường'}. Ngưỡng thực phải theo pin/tải.`;break;
case 'lag':y=x/100;s=`τ=${x.toFixed(0)} ms: đáp ứng bước đạt ~63% sau ${x.toFixed(0)} ms trong mô hình bậc một.`;break;
default:y=x;s=`Giá trị ${x.toFixed(2)}.`}
return {y,s}}
function resize(){const d=window.devicePixelRatio||1;const r=canvas.getBoundingClientRect();canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0)}
function curve(w,h,fn,color){ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();for(let px=0;px<w;px++){const u=px/Math.max(w,1),y=fn(u),py=h-28-y*(h-55);if(px===0)ctx.moveTo(px,py);else ctx.lineTo(px,py)}ctx.stroke()}
function axes(w,h,label){ctx.strokeStyle='#d7e5e0';ctx.lineWidth=1;for(let i=1;i<5;i++){ctx.beginPath();ctx.moveTo(0,i*h/5);ctx.lineTo(w,i*h/5);ctx.stroke()}ctx.fillStyle='#59736c';ctx.font='12px system-ui';ctx.fillText(label,12,h-9)}
function render(ts){if(!last)last=ts;const dt=Math.min(.05,(ts-last)/1000);last=ts;if(running)t+=dt;const w=canvas.clientWidth,h=canvas.clientHeight,x=Number(range.value),c=compute(x);val.textContent=x.toFixed(cfg.mode==='filter'?3:1);out.textContent=c.s;ctx.clearRect(0,0,w,h);
if(cfg.mode==='motor'){
 const cx=w/2,cy=h/2,arm=Math.min(w*.2,h*.36),locations=[[-1,-1],[1,-1],[1,1],[-1,1]],speed=[x,60,60,60];ctx.strokeStyle='#9abdb3';ctx.lineWidth=13;ctx.beginPath();ctx.moveTo(cx-arm,cy-arm);ctx.lineTo(cx+arm,cy+arm);ctx.moveTo(cx+arm,cy-arm);ctx.lineTo(cx-arm,cy+arm);ctx.stroke();locations.forEach(([sx,sy],i)=>{const px=cx+sx*arm,py=cy+sy*arm;ctx.fillStyle=i===0?'#cbece2':'#e8f5f1';ctx.strokeStyle='#177a70';ctx.lineWidth=2;ctx.beginPath();ctx.arc(px,py,19+speed[i]/8,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.save();ctx.translate(px,py);ctx.rotate((i%2?-1:1)*t*speed[i]/20);ctx.beginPath();ctx.moveTo(-24,0);ctx.lineTo(24,0);ctx.moveTo(0,-24);ctx.lineTo(0,24);ctx.stroke();ctx.restore();ctx.fillStyle='#243936';ctx.font='bold 15px system-ui';ctx.fillText(String(i+1),px-5,py+5)});ctx.fillStyle='#243936';ctx.font='13px system-ui';ctx.fillText('Mũi drone ↑ · rotor 1 đang thay đổi',12,h-12);
}else if(cfg.mode==='hover'){
 axes(w,h,'Mỗi cột = lực rotor hover (N)');const each=x*9.81/4,max=6.2,bw=Math.min(70,w/8),gap=(w-4*bw)/5;for(let i=0;i<4;i++){let px=gap+(bw+gap)*i,bar=Math.min(h-65,each/max*(h-65));ctx.fillStyle='#a5dfce';ctx.fillRect(px,h-36-bar,bw,bar);ctx.fillStyle='#243936';ctx.font='13px system-ui';ctx.fillText('R'+(i+1),px+bw/2-8,h-18);ctx.fillText(each.toFixed(2)+' N',px+3,h-42-bar)}
}else if(cfg.mode==='pitch'){
 const ang=x*Math.PI/180,cx=w/2,cy=h/2;ctx.strokeStyle='#abc7be';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(20,cy);ctx.lineTo(w-20,cy);ctx.stroke();ctx.save();ctx.translate(cx,cy);ctx.rotate(-ang);ctx.strokeStyle='#177a70';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(-Math.min(150,w*.3),0);ctx.lineTo(Math.min(150,w*.3),0);ctx.stroke();ctx.fillStyle='#177a70';ctx.fillRect(20,-14,35,28);ctx.restore();ctx.fillStyle='#243936';ctx.font='13px system-ui';ctx.fillText('Đường ngang = pitch 0°. Hình nghiêng theo góc đang chọn.',12,h-12);
}else{
 axes(w,h,'Trục ngang: thời gian/đầu vào chuẩn hóa · trục đứng: đáp ứng chuẩn hóa');
 if(cfg.mode==='drift'){curve(w,h,u=>.08+u*x/6,'#177a70');curve(w,h,u=>.08,'#bc8d43')}
 else if(cfg.mode==='thrust'){curve(w,h,u=>u*u,'#177a70');ctx.strokeStyle='#bc8d43';ctx.beginPath();let px=(x-100)/800*w;ctx.moveTo(px,h-28);ctx.lineTo(px,h-28-((x/900)**2)*(h-55));ctx.stroke()}
 else if(cfg.mode==='ratio'){curve(w,h,u=>u,'#177a70');curve(w,h,u=>Math.min(1,1/(c.y||1)),'#bc8d43')}
 else if(cfg.mode==='filter'){curve(w,h,u=>.5+.28*Math.sin(u*18),'#bc8d43');curve(w,h,u=>.5+.28*Math.sin(u*18)+(1-x)*.5*Math.sin(u*70+t),'#177a70')}
 else if(cfg.mode==='accel'){curve(w,h,u=>Math.max(0,Math.min(1,.5+c.y*u*u/18)),'#177a70');curve(w,h,u=>.5,'#bc8d43')}
 else if(cfg.mode==='track'){curve(w,h,u=>Math.min(1,u*u*c.y/6),'#177a70');curve(w,h,u=>.5,'#bc8d43')}
 else if(cfg.mode==='battery'){curve(w,h,u=>x<3.4?.25:x<3.6?.5:.75,'#177a70')}
 else if(cfg.mode==='lag'){curve(w,h,u=>1-Math.exp(-u*800/x),'#177a70');curve(w,h,u=>1,'#bc8d43')}
 else{let gain=cfg.mode==='step'?Math.max(.3,10/x):cfg.mode==='delay'?Math.max(.3,2-x/50):Math.max(.2,x/3);curve(w,h,u=>1-Math.exp(-u*6*Math.max(.2,gain))*(Math.cos(u*8*(1+gain*.6))+.12*Math.sin(u*8*gain)),'#177a70');curve(w,h,u=>1,'#bc8d43')}
}requestAnimationFrame(render)}
range.addEventListener('input',()=>{});window.addEventListener('resize',resize);resize();requestAnimationFrame(render);
document.getElementById('pause').onclick=()=>{running=!running;document.getElementById('pause').textContent=running?'Tạm dừng':'Tiếp tục'};
document.getElementById('reset').onclick=()=>{range.value=cfg.initial;t=0;running=true;document.getElementById('pause').textContent='Tạm dừng'};
document.getElementById('copy').onclick=async()=>{const value=document.getElementById('sample-code').textContent;let ok=false;try{if(navigator.clipboard){await navigator.clipboard.writeText(value);ok=true}}catch(e){}if(!ok){const box=document.createElement('textarea');box.value=value;document.body.appendChild(box);box.select();ok=document.execCommand('copy');box.remove()}document.getElementById('copy').textContent=ok?'Đã sao chép':'Chọn code để sao chép';setTimeout(()=>document.getElementById('copy').textContent='Copy',1600)};
const rotorLab=document.querySelector('.rotor-lab');if(rotorLab){const inputs=[...rotorLab.querySelectorAll('input')];function updateRotors(){const raw=inputs.map(e=>Number(e.value)),F=raw.map(v=>rotorLab.dataset.rotorMode==='speed'?5*(v/100)**2:v),a=.25/Math.sqrt(2),T=F.reduce((s,v)=>s+v,0),tx=a*(F[0]-F[1]-F[2]+F[3]),ty=-a*(F[0]+F[1]-F[2]-F[3]),tz=.02*(F[0]-F[1]+F[2]-F[3]);raw.forEach((v,i)=>document.getElementById('rotor-v-'+(i+1)).textContent=v.toFixed(rotorLab.dataset.rotorMode==='speed'?0:2));document.getElementById('rotor-output').textContent=`T=${T.toFixed(2)} N · τx=${tx.toFixed(3)} N·m · τy=${ty.toFixed(3)} N·m · τz=${tz.toFixed(3)} N·m · az=${(T/1.2-9.81).toFixed(2)} m/s² (m=1,2 kg)`}inputs.forEach(e=>e.addEventListener('input',updateRotors));updateRotors()}
function math(){if(!window.katex)return;document.querySelectorAll('[data-math]').forEach(el=>{try{katex.render(el.dataset.math,el,{displayMode:true,throwOnError:true})}catch(e){el.title=e.message}})}
math();window.addEventListener('load',math);
const sections=[...document.querySelectorAll('main section[id]')];const links=[...document.querySelectorAll('.sidebar a[href^="#"]')];const obs=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){links.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}})},{rootMargin:'-20% 0px -65% 0px'});sections.forEach(s=>obs.observe(s));
})();
"""

def make_code(n, mode):
    examples = {
      1:"""# Quy ước X: trước-trái=1, trước-phải=2, sau-phải=3, sau-trái=4\nrotors = {1:'trước-trái',2:'trước-phải',3:'sau-phải',4:'sau-trái'}\nfor i, location in rotors.items():\n    print(f'Tăng rotor {i} ({location}): tổng lực nâng tăng; kiểm tra mô men roll/pitch/yaw theo dấu mixer')""",
      2:"""import numpy as np\nm, g, kT = 1.2, 9.81, 1.2e-5\nT_each = m*g/4\nomega_hover = np.sqrt(T_each/kT)\nprint(f'{T_each:.3f} N/rotor, {omega_hover:.1f} rad/s')""",
      3:"""import numpy as np\ndef q_normalize(q):\n    q = np.asarray(q, dtype=float)\n    return q / np.linalg.norm(q)\ndef q_from_yaw(yaw):\n    return q_normalize([np.cos(yaw/2),0,0,np.sin(yaw/2)])\nprint(q_from_yaw(np.deg2rad(90)))""",
      4:"""import numpy as np\ndef vertical_accel(thrust, mass=1.2):\n    return thrust/mass - 9.81  # ENU: z hướng lên\nfor thrust in [0, 1.2*9.81, 15]:\n    print(thrust, vertical_accel(thrust))""",
      5:"""# Gyro đứng yên: lấy trung bình để tìm bias\nfrom statistics import mean\nsamples_rad_s = [0.018,0.017,0.019,0.018]\nbias = mean(samples_rad_s)\ncorrected = [v-bias for v in samples_rad_s]\nprint('bias rad/s =', bias, 'mean corrected =', mean(corrected))""",
      6:"""typedef struct { float kp,ki,kd,integral,prev_meas; } PID;\nfloat pid_step(PID *p,float set,float meas,float dt,float limit){\n  float e=set-meas, d=-(meas-p->prev_meas)/dt;\n  float candidate=p->integral+e*dt;\n  float raw=p->kp*e+p->ki*candidate+p->kd*d;\n  if(raw<limit && raw>-limit) p->integral=candidate;\n  p->prev_meas=meas;\n  float u=p->kp*e+p->ki*p->integral+p->kd*d;\n  return u>limit?limit:(u<-limit?-limit:u);\n}""",
      7:"""def complementary(prev, gyro_rad_s, accel_angle_rad, dt, alpha=.98):\n    return alpha*(prev+gyro_rad_s*dt)+(1-alpha)*accel_angle_rad\nangle=0.0\nfor _ in range(1000):\n    angle=complementary(angle, 0.01, 0.0, .001)\nprint('estimated angle rad:', angle)""",
      8:"""import numpy as np\ndef deriv(state, thrust, mass=1.2):\n    z, vz = state\n    return np.array([vz, thrust/mass-9.81])\ndef rk4(f, x, dt, *args):\n    a=f(x,*args); b=f(x+dt*a/2,*args)\n    c=f(x+dt*b/2,*args); d=f(x+dt*c,*args)\n    return x+dt*(a+2*b+2*c+d)/6\nx=np.array([0.,0.])\nfor _ in range(1000): x=rk4(deriv,x,.01,1.2*9.81)\nprint(x)  # hover lý tưởng: gần [0,0]""",
      9:"""def cascade(angle_sp, angle, rate, dt, outer_kp, rate_pid):\n    rate_sp=outer_kp*(angle_sp-angle)\n    return rate_pid.step(rate_sp, rate, dt)  # mô men yêu cầu\n# rate_pid.step phải giới hạn output và chống windup.\n# Kiểm thử lần lượt hover, bước 10 độ, nhiễu xung.""",
      10:"""def control_tick(sensor, estimator, controller, t_us):\n    estimate=estimator.update(sensor, t_us)\n    return controller.update(estimate, t_us)\n# Không truyền true_state vào controller.\n# Log: t_us,gyro,accel,angle_est,angle_sp,motor_command""",
      11:"""# Ví dụ quy trình trong môi trường Linux đã chuẩn bị theo tài liệu PX4\n# make px4_sitl gz_x500\n# Mở QGroundControl, xác nhận MAVLink và vehicle armed state.\n# Bay thử trong SITL, tải ULog và đối chiếu setpoint/measurement.""",
      12:"""import numpy as np\ndef position_pd(p_sp, v_sp, p, v, kp=2., kd=1.5, amax=3.):\n    a=kp*(np.array(p_sp)-p)+kd*(np.array(v_sp)-v)\n    norm=np.linalg.norm(a)\n    return a if norm<=amax else a*amax/norm\nprint(position_pd([2,0],[0,0],np.zeros(2),np.zeros(2)))""",
      13:"""// Chu kỳ điều khiển 1 kHz: IMU -> estimate -> PID -> mixer -> ESC\nvoid control_tick(void) {\n  if (!imu_fresh() || !rc_valid()) { disarm_or_failsafe(); return; }\n  imu_sample_t s = imu_read();\n  attitude_t x = estimate_attitude(s);\n  torque_t u = attitude_rate_control(x, setpoint);\n  motor_cmd_t m = mixer_limit(u);\n  esc_write(m);\n}""",
      14:"""import numpy as np\nomega=np.array([200.,300.,400.,500.,600.])\nthrust=np.array([.48,1.08,1.92,3.00,4.32])\nkT=np.dot(omega**2,thrust)/np.dot(omega**2,omega**2)\nprint('kT N s^2/rad^2 =',kT)\nprint('residual N =',thrust-kT*omega**2)""",
      15:"""# Đọc log giàn thử và đo vọt lố; chỉ đổi một gain mỗi lần\nimport csv\nwith open('roll_log.csv',newline='') as f:\n    rows=list(csv.DictReader(f))\nsetpoint=float(rows[-1]['setpoint_deg'])\npeak=max(float(r['roll_deg']) for r in rows)\nprint('overshoot % =',100*(peak-setpoint)/max(abs(setpoint),1e-9))""",
      16:"""typedef enum { SAFE, ARMED, FLIGHT, FAILSAFE } state_t;\nstate_t next_state(state_t s,bool imu_ok,bool rc_ok,bool low_batt){\n  if(!imu_ok) return FAILSAFE;\n  if(s==FLIGHT && (!rc_ok || low_batt)) return FAILSAFE;\n  return s; // arm/disarm chỉ qua sự kiện được xác thực riêng\n}""",
      17:"""import numpy as np\n# Fit y(t)=1-exp(-t/tau) trên log đáp ứng bước đã đồng bộ thời gian\nt=np.linspace(0,.4,41); tau_true=.08\ny=1-np.exp(-t/tau_true)\ncandidates=np.linspace(.01,.2,300)\nerrors=[np.mean((y-(1-np.exp(-t/tau)))**2) for tau in candidates]\nprint('tau fitted =',candidates[np.argmin(errors)],'s')"""
    }
    return examples[n]

def make_diagram(n):
    if n == 1:
        return '''<svg class="diagram" viewBox="0 0 680 280" role="img" aria-label="Quadcopter cấu hình X với bốn rotor và trục body">
        <g stroke="#9abdb3" stroke-width="12" stroke-linecap="round"><path d="M230 50L450 230M450 50L230 230"/></g>
        <g fill="#d5eee6" stroke="#187b71" stroke-width="3"><circle cx="230" cy="50" r="36"/><circle cx="450" cy="50" r="36"/><circle cx="450" cy="230" r="36"/><circle cx="230" cy="230" r="36"/><circle cx="340" cy="140" r="39"/></g>
        <g fill="#24443e" font-size="17" font-family="system-ui" font-weight="700" text-anchor="middle"><text x="230" y="56">1 ↻</text><text x="450" y="56">2 ↺</text><text x="450" y="236">3 ↻</text><text x="230" y="236">4 ↺</text><text x="340" y="146">BODY</text></g>
        <path d="M340 104V40M300 140H135" stroke="#187b71" stroke-width="3" marker-end="url(#arrow)"/><defs><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5 0 9Z" fill="#187b71"/></marker></defs>
        <g fill="#187b71" font-size="14" font-family="system-ui"><text x="350" y="35">+x body · mũi</text><text x="20" y="145">+y body · trái</text><text x="18" y="265">Body FLU nhìn từ trên; chiều quay là quy ước của sơ đồ này.</text></g></svg>'''
    if n == 2:
        return '''<svg class="diagram" viewBox="0 0 680 260" role="img" aria-label="Cánh quạt đẩy không khí xuống, phản lực nâng rotor lên"><defs><marker id="force" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#177a70"/></marker><marker id="air" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#bc8d43"/></marker></defs><path d="M170 110H510" stroke="#243936" stroke-width="12" stroke-linecap="round"/><ellipse cx="340" cy="112" rx="160" ry="15" fill="#cee8e0" opacity=".8"/><path d="M340 112V20" stroke="#177a70" stroke-width="5" marker-end="url(#force)"/><g stroke="#bc8d43" stroke-width="4" marker-end="url(#air)"><path d="M250 135V218M340 135V218M430 135V218"/></g><g fill="#243936" font-family="system-ui" font-size="17"><text x="354" y="42">Phản lực T hướng lên</text><text x="243" y="248">Không khí được đẩy xuống → động lượng tăng</text><text x="18" y="100">Mặt cắt rotor</text></g></svg>'''
    if n == 4:
        return '''<svg class="diagram" viewBox="0 0 680 260" role="img" aria-label="Lực nâng trong body được quay sang world và cộng với trọng lực"><defs><marker id="dyn" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5 0 9Z" fill="#177a70"/></marker></defs><path d="M85 215H580M85 215V25" stroke="#9abdb3" stroke-width="2"/><g fill="#60726e" font-family="system-ui" font-size="16"><text x="583" y="220">x world</text><text x="40" y="28">z world</text></g><circle cx="330" cy="138" r="24" fill="#d5eee6" stroke="#177a70" stroke-width="3"/><path d="M250 167L405 110" stroke="#243936" stroke-width="9" stroke-linecap="round"/><path d="M330 138L365 45" stroke="#177a70" stroke-width="5" marker-end="url(#dyn)"/><path d="M330 138V225" stroke="#bc8d43" stroke-width="5"/><g fill="#243936" font-family="system-ui" font-size="16"><text x="375" y="55">T theo z body</text><text x="343" y="238">mg theo −z world</text><text x="430" y="102">thân nghiêng → lực có thành phần ngang</text></g></svg>'''
    labels = {
      2:('Tốc độ rotor','Lực & mô men','Mixer / chuyển động'),3:('Euler / quaternion','Ma trận quay','Vector world'),
      4:('Lệnh rotor','Lực + mô men','Tích phân trạng thái'),5:('IMU thật','Bias + nhiễu','Hiệu chuẩn / lọc'),
      6:('Góc đặt','PID góc / rate','Motor + plant'),7:('Gyro + accel','Bộ lọc','Góc ước lượng'),
      8:('Input rotor','f(x,u) + RK4','Trạng thái 6-DOF'),9:('Góc đặt','Vòng góc → rate','Mixer → drone'),
      10:('Plant + cảm biến','Estimator','Controller + mixer'),11:('Gazebo SITL','PX4 / ArduPilot','QGroundControl'),
      12:('Waypoint','Sinh quỹ đạo','Vòng vị trí'),13:('IMU / RC','STM32 + FreeRTOS','ESC / motor'),
      14:('Motor trên giàn','Cân lực + IMU','Fit tham số'),15:('Lệnh góc nhỏ','Giàn thử 1 trục','Log + chỉnh PID'),
      16:('Pre-arm','Flight','Failsafe / log'),17:('Mô phỏng','Bay thật + log','Cập nhật mô hình')}
    a,b,c=(esc(v) for v in labels[n])
    return f'''<svg class="diagram" viewBox="0 0 680 150" role="img" aria-label="Sơ đồ luồng dữ liệu bài {n}"><defs><marker id="arr" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5 0 9Z" fill="#187b71"/></marker></defs><g fill="#e8f5f1" stroke="#aad3c8"><rect x="12" y="42" width="180" height="65" rx="14"/><rect x="250" y="42" width="180" height="65" rx="14"/><rect x="488" y="42" width="180" height="65" rx="14"/></g><g stroke="#187b71" stroke-width="3" marker-end="url(#arr)"><path d="M197 74H242"/><path d="M435 74H480"/></g><g fill="#24443e" font-size="16" font-family="system-ui" font-weight="700" text-anchor="middle"><text x="102" y="80">{a}</text><text x="340" y="80">{b}</text><text x="578" y="80">{c}</text></g></svg>'''

def render_theory(n):
    parts=[]
    for title, body, latex, explanation in THEORY[n]:
        formula=f'<div class="formula" data-math="{esc(latex)}"><span class="fallback">Công thức: {esc(explanation)}</span></div>' if latex else ''
        parts.append(f'<div class="theory-block"><h3>{esc(title)}</h3><p>{esc(body)}</p>{formula}<p class="small">{esc(explanation)}</p></div>')
    return ''.join(parts)

def render_references(n):
    if n not in REFERENCES:return ''
    links=''.join(f'<li><a href="{esc(url)}" target="_blank" rel="noopener">{esc(title)}</a></li>' for title,url in REFERENCES[n])
    return f'<h3>Đọc thêm từ tài liệu gốc</h3><ul>{links}</ul>'

def render_rotor_lab(n):
    if n not in (1,2):return ''
    speed=n==1
    title='Bốn tốc độ rotor' if speed else 'Bốn lực rotor và ma trận mixer'
    desc=('Mô hình giả định Ti=5·(speed_i/100)² N; kéo bốn rotor để thấy tổng lực và mô men.' if speed else 'Mỗi thanh là lực Ti (N); cánh tay đòn từ tâm đến rotor l=0,25 m, c=kQ/kT=0,02 m.')
    lo,hi,step,value=(0,100,1,77) if speed else (0,5,.05,2.94)
    unit='%' if speed else 'N'
    sliders=''.join(f'<label>Rotor {i} ({"trước-trái" if i==1 else "trước-phải" if i==2 else "sau-phải" if i==3 else "sau-trái"}): <output id="rotor-v-{i}"></output> {unit}<input class="rotor-input" type="range" min="{lo}" max="{hi}" step="{step}" value="{value}" aria-label="Rotor {i}"></label>' for i in range(1,5))
    return f'<h3>{title}</h3><p>{desc}</p><div class="rotor-lab" data-rotor-mode="{"speed" if speed else "force"}">{sliders}<div class="rotor-output" id="rotor-output" aria-live="polite"></div></div><p class="small">Quy ước FLU; rotor 1–4: trước-trái, trước-phải, sau-phải, sau-trái; chiều quay 1/3 CW, 2/4 CCW nhìn từ trên. Dấu yaw theo quy ước này. Các hệ số lực chỉ để học phép nhân ma trận.</p>'

def build_lesson(info, d):
    n=info['number']; short, concept, latex, unit, second, label, lo, hi, initial, mode, exercise, q1,a1,q2,a2,q3,a3=d
    prev=f'bai-{n-1:02}.html' if n>1 else 'nen-tang-toan.html'; nxt=f'bai-{n+1:02}.html' if n<17 else 'index.html'
    bullets=''.join(f'<li>{esc(b)}</li>' for b in info['bullets'][:8])
    questions=''.join(f'<div class="quiz"><strong>{level}: {esc(q)}</strong><details><summary>Xem đáp án</summary><p>{esc(a)}</p></details></div>' for level,q,a in [('Cơ bản',q1,a1),('Vận dụng',q2,a2),('Nâng cao',q3,a3)])
    code=esc(make_code(n,mode))
    config=__import__('json').dumps(dict(mode=mode,initial=initial),ensure_ascii=False)
    pre_text=info['pre'] + ('; Bài 0: vector, ma trận và phép quay.' if n in (2,3,4,7,8,10,12,17) else '')
    return f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bài {n}: {esc(info['title'])} · Giáo án Drone</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.18.0/katex.min.css"><style>{CSS}</style></head><body>
<div class="layout"><aside class="sidebar"><div class="brand">DRONE LAB · BÀI {n:02}</div><a href="index.html">← Toàn bộ lộ trình</a><a href="nen-tang-toan.html">Nền tảng vector & ma trận</a><hr><div class="chapter-links"><a href="#mo-dau">Mở đầu</a><a href="#ly-thuyet">Lý thuyết</a><a href="#mo-phong">Mô phỏng</a><a href="#thuc-hanh">Thực hành</a><a href="#loi">Lỗi thường gặp</a><a href="#tu-kiem-tra">Tự kiểm tra</a><a href="#tom-tat">Tóm tắt</a></div></aside><main class="content">
<section class="hero" id="mo-dau"><div class="eyebrow">Giai đoạn {1 if n<=7 else 2 if n<=12 else 3 if n<=16 else 4} · Bài {n:02}/17</div><h1>{esc(info['title'])}</h1><p class="lead">{esc(info['goal'])}</p><div class="meta"><div class="mini"><strong>Bạn sẽ làm được</strong><br>{esc(d[1])}</div><div class="mini"><strong>Cần biết trước</strong><br>{esc(pre_text)} {('<a href="nen-tang-toan.html">Ôn Bài 0 →</a>' if n in (2,3,4,7,8,10,12,17) else '')}</div></div><div class="flow"><span>Trực giác</span> → <span>Mô hình</span> → <span>Thử nghiệm</span> → <span>Kiểm tra</span></div></section>
<section class="card" id="ly-thuyet"><div class="eyebrow">01 · Nền tảng</div><h2>Từ hiện tượng đến mô hình</h2><p>{esc(concept)}</p>{make_diagram(n)}<div class="formula" data-math="{esc(latex)}"><span class="fallback">{esc(unit)}</span></div><p class="small">{esc(unit)}</p><div class="callout"><strong>Điểm cần nhớ.</strong> {esc(second)}</div>{render_theory(n)}{topic_figure(n)}<h3>Ví dụ giải nhanh</h3><p><strong>Đề:</strong> {esc(q1)}</p><p><strong>Cách làm:</strong> {esc(a1)}</p><h3>Nội dung cần nắm</h3><ul>{bullets}</ul><div class="callout warn"><strong>Giới hạn mô hình.</strong> Mô phỏng trong trang dùng mô hình rút gọn để làm rõ một quan hệ. Kết quả thiết kế drone thật cần đo tham số, kiểm thử và đối chiếu tài liệu phần cứng.</div></section>
<section class="card" id="mo-phong"><div class="eyebrow">02 · Phòng thí nghiệm</div><h2>Thay tham số, xem kết quả</h2><p>{esc(exercise)}</p><div class="controls"><label for="param">{esc(label)}: <strong id="param-value"></strong><input id="param" type="range" min="{lo}" max="{hi}" step="{.001 if mode=='filter' else .1}" value="{initial}"></label><button id="pause" type="button">Tạm dừng</button><button id="reset" class="secondary" type="button">Đặt lại</button></div><canvas id="lab-canvas" role="img" aria-label="Đồ thị phản hồi tương tác"></canvas><div class="readout" id="readout" aria-live="polite"></div><p class="small">Đồ thị minh họa mô hình đơn giản; dòng số liệu trên dùng công thức được ghi rõ và cập nhật theo thanh trượt.</p>{render_rotor_lab(n)}</section>
<section class="card" id="thuc-hanh"><div class="eyebrow">03 · Thực hành</div><h2>Làm theo ba bước</h2><div class="step"><b>1</b><div><strong>Chuẩn bị.</strong> {esc(info['pre'])} Ghi quy ước hệ trục, đơn vị và giả thiết.</div></div><div class="step"><b>2</b><div><strong>Thực hiện.</strong> {esc(info['practice'] or exercise)}</div></div><div class="step"><b>3</b><div><strong>Kiểm tra.</strong> So sánh kết quả với ca giới hạn hoặc giá trị có thể tính tay; ghi sai số và lý do nếu lệch.</div></div><div class="codebar"><strong>Code tham khảo</strong><button id="copy" class="secondary" type="button">Copy</button></div><pre><code id="sample-code">{code}</code></pre><p class="small">Đoạn code là ví dụ tối giản cho bước thực hành; xem chú thích và kiểm tra đơn vị trước khi đưa vào hệ thống thật.</p></section>
<section class="card" id="loi"><div class="eyebrow">04 · Chẩn đoán</div><h2>Lỗi thường gặp</h2><table><thead><tr><th>Hiện tượng</th><th>Nguyên nhân cần kiểm tra</th><th>Cách xử lý</th></tr></thead><tbody><tr><td>Kết quả ngược trực giác</td><td>Quy ước trục, dấu và đơn vị</td><td>Vẽ trục, kiểm tra một ca tính tay</td></tr><tr><td>Đồ thị không ổn định</td><td>Tham số, bước thời gian, bão hòa</td><td>Giảm bước thời gian/gain, xem log</td></tr><tr><td>Đo và mô hình lệch nhau</td><td>{esc(info['errors'] or 'Nhiễu và sai số mô hình')}</td><td>Đo lại từng khối, ghi giả thiết và so phần dư</td></tr></tbody></table></section>
<section class="card" id="tu-kiem-tra"><div class="eyebrow">05 · Tự kiểm tra</div><h2>Ba mức độ</h2>{questions}</section>
<section class="card" id="tom-tat"><div class="eyebrow">06 · Ghi nhớ</div><h2>Sau bài này</h2><ul><li>{esc(concept)}</li><li>{esc(second)}</li><li>Hãy lưu kết quả thí nghiệm và kiểm chứng bằng ca tính tay trước khi sang bài sau.</li></ul><p>{'Bài sau: '+esc(PROMPT_DATA[n]['title']) if n<17 else 'Bạn đã đi hết lộ trình. Hãy dùng log và phép đo để cải thiện mô hình của chính mình.'}</p>{render_references(n)}</section>
<nav class="nav" aria-label="Điều hướng bài học"><a href="{prev}">← {('Bài 0: Toán nền' if n==1 else 'Bài '+str(n-1))}</a><a href="index.html">Lộ trình</a><a href="{nxt}">{('Mục lục' if n==17 else 'Bài '+str(n+1))} →</a></nav></main></div><script id="lesson-config" type="application/json">{config}</script><script src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.18.0/katex.min.js"></script><script>{JS}</script></body></html>'''

def build_index():
    groups=[('01 · Cơ sở lý thuyết',1,7),('02 · Mô phỏng',8,12),('03 · Phần cứng và thực nghiệm',13,16),('04 · Hoàn thiện',17,17)]
    cards=''
    for group,start,end in groups:
        cards+=f'<section class="card"><div class="eyebrow">{esc(group)}</div><div class="course-grid">'
        for i in range(start,end+1):
            p=PROMPT_DATA[i-1]
            cards+=f'<a class="lesson-card" href="bai-{i:02}.html"><span>BÀI {i:02}</span><h2>{esc(p["title"])}</h2><p>{esc(p["goal"])}</p><b>Vào bài →</b></a>'
        cards+='</div></section>'
    return f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Giáo án phát triển Drone Quadcopter</title><style>{CSS}.index{{max-width:1100px;margin:auto;padding:25px}}.course-grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}}.lesson-card{{display:block;text-decoration:none;color:var(--ink);border:1px solid var(--line);border-radius:15px;padding:20px;background:#fff;transition:transform .2s,box-shadow .2s}}.lesson-card:hover{{transform:translateY(-3px);box-shadow:var(--shadow)}}.lesson-card span,.lesson-card b{{color:var(--accent)}}.lesson-card h2{{font-size:1.2rem;margin:8px 0}}.lesson-card p{{color:var(--muted);font-size:.94rem}}@media(prefers-reduced-motion:reduce){{.lesson-card{{transition:none}}}}</style></head><body><main class="index"><header class="hero"><div class="eyebrow">Giáo án thực hành · Bài 0 + 17 bài</div><h1>Phát triển drone quadcopter</h1><p class="lead">Từ vector và ma trận đến lực, điều khiển, mô phỏng, flight controller, bay thử và nhận dạng hệ thống. Dành cho kỹ sư embedded đã biết C, STM32 và FreeRTOS.</p><div class="flow"><span>Bài 0: Toán nền</span> → <span>7 bài lý thuyết</span> → <span>5 bài mô phỏng</span> → <span>4 bài thực nghiệm</span> → <span>1 bài tổng hợp</span></div><a href="nen-tang-toan.html"><button>Bắt đầu với vector & ma trận →</button></a></header><section class="card"><div class="eyebrow">Kiến thức toán cần dùng</div><h2>Học đến đâu dùng đến đó</h2><table><thead><tr><th>Kiến thức</th><th>Gặp ở bài</th><th>Dùng để làm gì</th></tr></thead><tbody><tr><td>Vector, tích vô hướng, tích có hướng</td><td>0, 1, 2, 4</td><td>Lực, mô men, hệ tọa độ</td></tr><tr><td>Nhân ma trận, chuyển vị, nghịch đảo</td><td>0, 2, 3</td><td>Mixer và đổi body ↔ world</td></tr><tr><td>Đạo hàm, tích phân</td><td>4, 6, 8</td><td>Động lực học và PID</td></tr><tr><td>Xác suất, phương sai</td><td>5, 7, 10</td><td>Nhiễu cảm biến và Kalman</td></tr></tbody></table><p><a href="nen-tang-toan.html">Mở Bài 0: Vector, ma trận và phép quay →</a></p></section>{cards}<p class="small">Mỗi bài là một file HTML độc lập, có thể mở trực tiếp. Công thức KaTeX cần kết nối mạng; nội dung và mô phỏng vẫn đọc/chạy khi offline.</p></main></body></html>'''

for p,d in zip(PROMPT_DATA,DATA):
    (ROOT/f'bai-{p["number"]:02}.html').write_text(build_lesson(p,d),encoding='utf-8')
(ROOT/'index.html').write_text(build_index(),encoding='utf-8')
(ROOT/'nen-tang-toan.html').write_text(build_math(CSS),encoding='utf-8')
print('Built index.html, math prerequisite and 17 standalone lessons')
